PROGRAM MotionControl
VAR_INPUT
  StartBtn : BOOL; StopBtn : BOOL; HomeBtn : BOOL;
  JogForward : BOOL; JogReverse : BOOL;
  LimitPositive : BOOL; LimitNegative : BOOL; HomeSensor : BOOL;
  TargetPosition : INT := 5000; MoveVelocity : INT := 1000;
  Acceleration : INT := 500; Deceleration : INT := 500;
  EmergencyStop : BOOL;
END_VAR
VAR_OUTPUT
  PulseOut : BOOL; DirectionOut : BOOL;
  IsRunning : BOOL; IsHomed : BOOL; IsMoving : BOOL; IsAtTarget : BOOL;
  FaultAlarm : BOOL; CurrentPosition : INT;
END_VAR
VAR
  AxisFault : BOOL := FALSE; AxisEnabled : BOOL := FALSE;
  AxisBusy : BOOL := FALSE; AxisHomed : BOOL := FALSE;
  MoveMode : INT := 0; SetpointPosition : INT := 0;
  ActualPosition : INT := 0; PositionError : INT := 0;
  VelocityCmd : INT := 0; LimitFaultLatch : BOOL := FALSE;
  PulseActive : BOOL := FALSE; PulseDir : BOOL := FALSE;
  PulseAccum : INT := 0; PulseTarget : INT := 0;
END_VAR

IF StartBtn AND NOT StopBtn AND NOT AxisFault THEN
  AxisEnabled := TRUE;
ELSIF StopBtn OR AxisFault THEN
  AxisEnabled := FALSE;
END_IF
IsRunning := AxisEnabled;

IF LimitPositive OR LimitNegative THEN LimitFaultLatch := TRUE; END_IF
IF HomeBtn AND NOT LimitPositive AND NOT LimitNegative THEN
  LimitFaultLatch := FALSE;
END_IF
AxisFault := LimitFaultLatch; FaultAlarm := AxisFault;

IF NOT AxisEnabled THEN MoveMode := 0;
ELSIF HomeBtn AND AxisEnabled THEN MoveMode := 1;
ELSIF LimitFaultLatch OR EmergencyStop THEN MoveMode := 4;
ELSIF JogForward OR JogReverse THEN MoveMode := 2;
ELSIF StartBtn AND AxisEnabled AND AxisHomed THEN MoveMode := 3;
ELSE MoveMode := 0;
END_IF

IF MoveMode = 0 THEN
  VelocityCmd := 0; PulseActive := FALSE; AxisBusy := FALSE;
ELSIF MoveMode = 1 THEN
  PulseDir := FALSE; PulseActive := TRUE; VelocityCmd := 200;
  IF HomeSensor THEN
    PulseActive := FALSE; AxisHomed := TRUE; ActualPosition := 0; MoveMode := 0;
  END_IF
  IF LimitNegative THEN PulseDir := TRUE; END_IF
ELSIF MoveMode = 2 THEN
  IF JogForward AND NOT LimitPositive THEN
    PulseDir := TRUE; PulseActive := TRUE; VelocityCmd := 500;
  ELSIF JogReverse AND NOT LimitNegative THEN
    PulseDir := FALSE; PulseActive := TRUE; VelocityCmd := 500;
  ELSE PulseActive := FALSE; VelocityCmd := 0; END_IF
ELSIF MoveMode = 3 THEN
  PulseDir := TargetPosition > ActualPosition;
  PulseTarget := TargetPosition; PulseActive := TRUE;
  VelocityCmd := MoveVelocity; AxisBusy := TRUE;
  IF ActualPosition >= TargetPosition - 10 AND ActualPosition <= TargetPosition + 10 THEN
    PulseActive := FALSE; AxisBusy := FALSE;
  END_IF
ELSIF MoveMode = 4 THEN
  PulseActive := FALSE; VelocityCmd := 0; AxisBusy := FALSE;
ELSE MoveMode := 0; END_IF

PulseOut := PulseActive;
IF PulseDir THEN DirectionOut := TRUE; ELSE DirectionOut := FALSE; END_IF

IF PulseActive AND PulseDir THEN ActualPosition := ActualPosition + 1;
ELSIF PulseActive AND NOT PulseDir THEN ActualPosition := ActualPosition - 1; END_IF
CurrentPosition := ActualPosition;
IsHomed := AxisHomed; IsMoving := PulseActive;
IsAtTarget := NOT PulseActive AND AxisHomed AND MoveMode = 0;
PositionError := TargetPosition - ActualPosition;

END_PROGRAM
